'use strict'

import resource from '../../resource'
import { DIRECTION_EAST, DIRECTION_WEST } from '../../constant'
import { Enemy, randomInt, drawImage, isInside } from './common'

// The ghosts of the graveyard: they float through everything towards Link, a bit at random, and
// take many hits
const GHINI = { life: 9, contactDamage: 1 }
const SPEED = 1
const MIN_COURSE_STEPS = 30
const MAX_COURSE_STEPS = 70
// How far from the way to Link it may go, in radians
const WANDER = 1

const STATE_FLOATING = 'floating'

class Ghini extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, GHINI, random)
    this.vx = 0
    this.vy = 0
    this.course = 0
    this.facing = DIRECTION_EAST
    this.fx = x
    this.fy = y
  }

  start () {
    this.setState(STATE_FLOATING)
  }

  // On the screen, whatever is there
  canStandAt (map, x, y) {
    return isInside(map, x, y, this.width, this.height)
  }

  act (map, link) {
    if (this.state !== STATE_FLOATING) {
      return
    }
    if (this.steps >= this.course) {
      const angle = Math.atan2(link.y - this.y, link.x - this.x) + (this.random() - 0.5) * 2 * WANDER
      this.vx = Math.cos(angle) * SPEED
      this.vy = Math.sin(angle) * SPEED
      this.course = this.steps + randomInt(this.random, MIN_COURSE_STEPS, MAX_COURSE_STEPS)
    }
    const x = this.fx + this.vx
    const y = this.fy + this.vy
    if (this.canStandAt(map, Math.round(x), Math.round(y))) {
      this.fx = x
      this.fy = y
      this.x = Math.round(x)
      this.y = Math.round(y)
    }
    if (this.vx !== 0) {
      this.facing = this.vx > 0 ? DIRECTION_EAST : DIRECTION_WEST
    }
  }

  knockBack (map) {
    super.knockBack(map)
    this.fx = this.x
    this.fy = this.y
    this.course = 0
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`ghini_${this.facing}_move`), 0, this.x, this.y, this.width, this.height)
  }
}

export { Ghini }
